import subprocess, tempfile, os, sys, json, re, uuid
REAL = os.getcwd()
HOOK = os.path.join(REAL, ".claude", "hooks", "coord_hook.py")
def intro(cwd, env, opt):
    sid = str(uuid.uuid4())
    start = json.dumps({"hook_event_name": "SessionStart", "session_id": sid, "cwd": cwd, "source": "startup"})
    r = subprocess.run([sys.executable, HOOK] + opt, input=start, capture_output=True, text=True, cwd=cwd, env=env, timeout=60)
    end = json.dumps({"hook_event_name": "SessionEnd", "session_id": sid, "cwd": cwd})
    subprocess.run([sys.executable, HOOK] + opt, input=end, capture_output=True, text=True, cwd=cwd, env=env, timeout=60)
    try:
        return json.loads(r.stdout).get("hookSpecificOutput", {}).get("additionalContext", "")
    except ValueError:
        return ""
def runnable(text, cwd):
    paths = re.findall(r"python3 (\S*(?:coord|kbask)\.py)", text)
    names = {os.path.basename(p) for p in paths}
    return names == {"coord.py", "kbask.py"} and all(os.path.exists(os.path.join(cwd, os.path.expanduser(p))) for p in paths), sorted(set(paths))[:2]
base = {k: v for k, v in os.environ.items() if k not in ("KB_COORD_STORE", "CLAUDE_PROJECT_DIR")}
T = os.path.realpath(tempfile.mkdtemp())
subprocess.run(["git", "init", "-q", T])
json.dump({"hooks": ["coord"]}, open(os.path.join(T, "backlog.json"), "w"))
plugin_ok, plugin_paths = runnable(intro(T, dict(base, CLAUDE_PROJECT_DIR=T), ["--opt-in"]), T)
clone_ok, clone_paths = runnable(intro(REAL, dict(base, KB_COORD_STORE=os.path.join(tempfile.mkdtemp(), "c.sqlite")), []), REAL)
print("plugin workspace: the INTRO commands exist", plugin_ok, plugin_paths, "| kb clone: they exist", clone_ok, clone_paths)
sys.exit(0 if plugin_ok and clone_ok else 1)
